<header class="page">
  <div class="wrap">
    <h1>Women's Training Outcomes by District</h1>
    <p>Training completion rate &amp; employment 6 months after training — select two years to compare</p>
  </div>
</header>

<div class="wrap">

  <div class="card">
    <h2>Year selector <span class="tag">compare</span></h2>
    <div class="controls">
      <div class="field">
        <label for="yearA">Year A</label>
        <select id="yearA"></select>
      </div>
      <div class="field">
        <label for="yearB">Year B (comparison)</label>
        <select id="yearB"></select>
      </div>
      <span class="hint" id="compareHint"></span>
    </div>
  </div>

  <div class="card">
    <h2 id="tableAHead">Year A</h2>
    <div style="overflow-x:auto">
      <table id="tableA"></table>
    </div>
  </div>

  <div class="card">
    <h2 id="tableBHead">Year B</h2>
    <div style="overflow-x:auto">
      <table id="tableB"></table>
    </div>
  </div>

  <div class="card">
    <h2>Comparison (percentage-point change, B − A)</h2>
    <div style="overflow-x:auto">
      <table id="tableC"></table>
    </div>
  </div>

/* ---------- Rendering ---------- */
function yearTable(rows) {
  const head =
    "<thead><tr><th>District</th><th>Enrolled</th><th>Completed</th>" +
    "<th>Completion rate</th><th>Employed @ 6 mo</th><th>6-month employment rate</th></tr></thead>";
  const body = rows.map(r =>
    "<tr><td>" + r.district + "</td>" +
    "<td>" + fmtInt(r.women_enrolled) + "</td>" +
    "<td>" + fmtInt(r.completed_training) + "</td>" +
    barCell(completionRate(r)) +
    "<td>" + fmtInt(r.employed_at_6_months) + "</td>" +
    barCell(employmentRate(r)) + "</tr>"
  ).join("");
  return head + "<tbody>" + body + "</tbody>";
}

function compareTable(rowsA, rowsB) {
  const districts = rowsA.filter(r => r.district !== "All districts").map(r => r.district);
  const totalA = rowsA.find(r => r.district === "All districts");
  const totalB = rowsB.find(r => r.district === "All districts");
  const head =
    "<thead><tr><th>District</th><th>Completion A</th><th>Completion B</th><th>Δ</th>" +
    "<th>Employment A</th><th>Employment B</th><th>Δ</th></tr></thead>";
  let body = districts.map(d => {
    const a = rowsA.find(r => r.district === d);
    const b = rowsB.find(r => r.district === d);
    return "<tr><td>" + d + "</td>" +
      '<td class="num">' + fmtPct(completionRate(a)) + "</td>" +
      '<td class="num">' + fmtPct(completionRate(b)) + "</td>" +
      deltaCell(completionRate(a), completionRate(b)) +
      '<td class="num">' + fmtPct(employmentRate(a)) + "</td>" +
      '<td class="num">' + fmtPct(employmentRate(b)) + "</td>" +
      deltaCell(employmentRate(a), employmentRate(b)) + "</tr>";
  }).join("");
  if (totalA && totalB) {
    body += '<tfoot><tr><td>All districts</td>' +
      '<td class="num">' + fmtPct(completionRate(totalA)) + "</td>" +
      '<td class="num">' + fmtPct(completionRate(totalB)) + "</td>" +
      deltaCell(completionRate(totalA), completionRate(totalB)) +
      '<td class="num">' + fmtPct(employmentRate(totalA)) + "</td>" +
      '<td class="num">' + fmtPct(employmentRate(totalB)) + "</td>" +
      deltaCell(employmentRate(totalA), employmentRate(totalB)) + "</tr></tfoot>";
  }
  return head + "<tbody>" + body + "</tbody>";
}

function fillYears(years) {
  [selA, selB].forEach(sel => {
    sel.innerHTML = years.map(y => '<option value="' + y + '">' + y + "</option>").join("");
  });
  selA.value = String(years[0]);
  selB.value = String(years[1] || years[0]);
}

function render(data) {
  const yearA = +selA.value;
  const yearB = +selB.value;
  const rowsA = rowsForYear(data, yearA);
  const rowsB = rowsForYear(data, yearB);

  document.getElementById("tableAHead").textContent = "Year " + yearA + " — outcomes by district";
  document.getElementById("tableA").innerHTML = yearTable(rowsA);
  document.getElementById("tableBHead").textContent = "Year " + yearB + " — outcomes by district";
  document.getElementById("tableB").innerHTML = yearTable(rowsB);
  document.getElementById("tableC").innerHTML = compareTable(rowsA, rowsB);
  document.getElementById("compareHint").textContent =
    yearA === yearB
      ? "Tip: pick a different year for Year B to see year-on-year change."
      : "Comparing " + yearB + " against " + yearA + " (B − A, in percentage points).";
}

function renderSource(data) {
  const src = [...new Set(data.map(r => r.source))].join("; ") || "—";
  const districts = [...new Set(data.map(r => r.district))].sort().join(", ");
  const years = [...new Set(data.map(r => r.year))].sort((a, b) => a - b).join("–");
  document.getElementById("srcText").textContent = src;
  document.getElementById("coverageText").textContent =
    "Districts: " + districts + " · Years: " + years;
  document.getElementById("srcNote").textContent = /synthetic|fixture|sample/i.test(src)
    ? "Note: the declared source indicates this is a synthetic fixture dataset — figures are illustrative, not official statistics."
    : "";
}

/* ---------- Setup ---------- */
const selA = document.getElementById("yearA");
const selB = document.getElementById("yearB");

function init(data) {
  const years = [...new Set(data.map(r => r.year))].sort((a, b) => a - b);
  fillYears(years);
  renderSource(data);
  selA.addEventListener("change", () => render(data));
  selB.addEventListener("change", () => render(data));
  render(data);
}

/* Parse the CSV (district,year,women_enrolled,completed_training,employed_at_6_months,source). */
function parseCsv(text) {
  const lines = text.trim().split(/\r?\n/);
  const header = lines[0].split(",").map(s => s.trim());
  return lines.slice(1).filter(l => l.trim()).map(line => {
    const parts = line.split(",").map(s => s.trim());
    const row = {};
    header.forEach((h, i) => { row[h] = parts[i]; });
    return {
      district: row.district,
      year: +row.year,
      women_enrolled: +row.women_enrolled,
      completed_training: +row.completed_training,
      employed_at_6_months: +row.employed_at_6_months,
      source: row.source || ""
    };
  }).filter(r => r.district && !isNaN(r.year));
}

/* Try to load the CSV first (works when served via a web server);
   otherwise fall back to the embedded copy. */
(async function boot() {
  try {
    const res = await fetch("women_livelihood_outcomes.csv", { cache: "no-store" });
    if (!res.ok) throw new Error("HTTP " + res.status);
    const rows = parseCsv(await res.text());
    if (rows.length) { init(rows); return; }
    throw new Error("empty CSV");
  } catch (e) {
    console.warn("Using embedded fallback data (" + e.message + ")");
    init(FALLBACK_DATA);
  }
})();
</script>
</body>
</html>

